(window.IND_GITA_V = window.IND_GITA_V || {})[1] = [{"v":1,"sp":"dhritarashtra","spm":null,"spl":"धृतराष्ट्र उवाच","spp":"before","sa":"धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः ।\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय ॥","iast":"dharmakṣetre kurukṣetre samavetā yuyutsavaḥ |\nmāmakāḥ pāṇḍavāścaiva kimakurvata sañjaya ||","read":"dharmakshetre kurukshetre samavetaa yuyutsavah |\nmaamakaah paandavaashchaiva kimakurvata sanjaya ||","spli":"dhṛtarāṣṭra uvāca","splr":"dhritaraashtra uvaacha","en":"Dhritarâshtra said: On the holy plain, on the field of Kuru, gathered together, eager for battle, what did they, O Sanjaya, my people and the Pândavas?","en2":"Tell me, O Sanjaya! Assembled on Kurukshetra, the centre of religious activity, desirous to fight, what indeed did my people and the Pândavas do?","en2r":null,"rv":null,"kid":null},{"v":2,"sp":"sanjaya","spm":null,"spl":"सञ्जय उवाच","spp":"before","sa":"दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा ।\nआचार्यमुपसङ्गम्य राजा वचनमब्रवीत् ॥","iast":"dṛṣṭvā tu pāṇḍavānīkaṃ vyūḍhaṃ duryodhanastadā |\nācāryamupasaṅgamya rājā vacanamabravīt ||","read":"drishtvaa tu paandavaaneekam vyoodham duryodhanastadaa |\naachaaryamupasangamya raajaa vachanamabraveet ||","spli":"sañjaya uvāca","splr":"sanjaya uvaacha","en":"Sanjaya said: Having seen arrayed the army of the Pândavas, the Prince Duryodhana approached his teacher, and spake these words:","en2":"But then King Duryodhana, having seen the Pândava forces in battle-array, approached his teacher Drona, and spoke these words:","en2r":null,"rv":null,"kid":null},{"v":3,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम् ।\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता ॥","iast":"paśyaitāṃ pāṇḍuputrāṇāmācārya mahatīṃ camūm |\nvyūḍhāṃ drupadaputreṇa tava śiṣyeṇa dhīmatā ||","read":"pashyaitaam paanduputraanaamaachaarya mahateem chamoom |\nvyoodhaam drupadaputrena tava shishyena dheemataa ||","spli":null,"splr":null,"en":"\"Behold this mighty host of the sons of Pându, O teacher, arrayed by the son of Drupada, thy wise disciple.","en2":"\"Behold, O Teacher! this mighty army of the sons of Pându, arrayed by the son of Drupada, thy gifted pupil.","en2r":null,"rv":null,"kid":null},{"v":4,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अत्र शूरा महेष्वासा भीमार्जुनसमा युधि ।\nयुयुधानो विराटश्च द्रुपदश्च महारथः ॥","iast":"atra śūrā maheṣvāsā bhīmārjunasamā yudhi |\nyuyudhāno virāṭaśca drupadaśca mahārathaḥ ||","read":"atra shooraa maheshvaasaa bheemaarjunasamaa yudhi |\nyuyudhaano viraatashcha drupadashcha mahaarathah ||","spli":null,"splr":null,"en":"Heroes are these, mighty bowmen, to Bhîma and Arjuna equal in battle: Yuyudhâna, Virâta, and Drupada of the great car.","en2":"\"Here (are) heroes, mighty archers, the equals in battle of Bhima and Arjuna—the great warriors Yuyudhâna, Virâta, Drupada; the valiant Dhrishtaketu, Chekitâna and the king of Kâshi; the best of men, Purujit, Kunti-Bhoja and Shaivya; the powerful Yudhâmanyu, and the brave Uttamaujas, the son of Subhadrâ, and the sons of Draupadi,—lords of great chariots.","en2r":"1.4-6","rv":null,"kid":null},{"v":5,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान् ।\nपुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुङ्गवः ॥","iast":"dhṛṣṭaketuścekitānaḥ kāśirājaśca vīryavān |\npurujitkuntibhojaśca śaibyaśca narapuṅgavaḥ ||","read":"dhrishtaketushchekitaanah kaashiraajashcha veeryavaan |\npurujitkuntibhojashcha shaibyashcha narapungavah ||","spli":null,"splr":null,"en":"Drishtaketu, Chekitâna and the valiant King of Kâshi, Purujit and Kuntibhoja, and Shaivya, bull among men;","en2":"\"Here (are) heroes, mighty archers, the equals in battle of Bhima and Arjuna—the great warriors Yuyudhâna, Virâta, Drupada; the valiant Dhrishtaketu, Chekitâna and the king of Kâshi; the best of men, Purujit, Kunti-Bhoja and Shaivya; the powerful Yudhâmanyu, and the brave Uttamaujas, the son of Subhadrâ, and the sons of Draupadi,—lords of great chariots.","en2r":"1.4-6","rv":null,"kid":null},{"v":6,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान् ।\nसौभद्रो द्रौपदेयाश्च सर्व एव महारथाः ॥","iast":"yudhāmanyuśca vikrānta uttamaujāśca vīryavān |\nsaubhadro draupadeyāśca sarva eva mahārathāḥ ||","read":"yudhaamanyushcha vikraanta uttamaujaashcha veeryavaan |\nsaubhadro draupadeyaashcha sarva eva mahaarathaah ||","spli":null,"splr":null,"en":"Yudhâmanyu the strong, and Uttamaujas the brave; Saubhadra and the Draupadeyas, all of great cars.","en2":"\"Here (are) heroes, mighty archers, the equals in battle of Bhima and Arjuna—the great warriors Yuyudhâna, Virâta, Drupada; the valiant Dhrishtaketu, Chekitâna and the king of Kâshi; the best of men, Purujit, Kunti-Bhoja and Shaivya; the powerful Yudhâmanyu, and the brave Uttamaujas, the son of Subhadrâ, and the sons of Draupadi,—lords of great chariots.","en2r":"1.4-6","rv":null,"kid":null},{"v":7,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम ।\nनायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते ॥","iast":"asmākaṃ tu viśiṣṭā ye tānnibodha dvijottama |\nnāyakā mama sainyasya saṃjñārthaṃ tānbravīmi te ||","read":"asmaakam tu vishishtaa ye taannibodha dvijottama |\nnaayakaa mama sainyasya samjnaartham taanbraveemi te ||","spli":null,"splr":null,"en":"Know further all those who are our chiefs, O best of the twice-born, the leaders of my army; these I name to thee for thy information:","en2":"\"Hear also, O Best of the twice-born! the names of those who (are) distinguished amongst ourselves, the leaders of my army. These I relate (to you) for your information.","en2r":null,"rv":null,"kid":null},{"v":8,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः ।\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च ॥","iast":"bhavānbhīṣmaśca karṇaśca kṛpaśca samitiñjayaḥ |\naśvatthāmā vikarṇaśca saumadattistathaiva ca ||","read":"bhavaanbheeshmashcha karnashcha kripashcha samitinjayah |\nashvatthaamaa vikarnashcha saumadattistathaiva cha ||","spli":null,"splr":null,"en":"Thou, Lord, and Bhîshma, and Karna and Kripa, conquering in battle; Ashvatthâmâ, Vikarna, and Saumadatti also;","en2":"\"Yourself and Bhishma and Karna and Kripa, the victorious in war. Asvatthâmâ and Vikarna and Jayadratha, the son of Somadatta.","en2r":null,"rv":null,"kid":null},{"v":9,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः ।\nनानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः ॥","iast":"anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ |\nnānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ ||","read":"anye cha bahavah shooraa madarthe tyaktajeevitaah |\nnaanaashastrapraharanaah sarve yuddhavishaaradaah ||","spli":null,"splr":null,"en":"And many others, heroes, for my sake renouncing their lives, with divers weapons and missiles, and all well-skilled in war.","en2":"\"And many other heroes also, well-skilled in fight, and armed with many kinds of weapons, are here, determined to lay down their lives for my sake.","en2r":null,"rv":null,"kid":null},{"v":10,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम् ।\nपर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम् ॥","iast":"aparyāptaṃ tadasmākaṃ balaṃ bhīṣmābhirakṣitam |\nparyāptaṃ tvidameteṣāṃ balaṃ bhīmābhirakṣitam ||","read":"aparyaaptam tadasmaakam balam bheeshmaabhirakshitam |\nparyaaptam tvidameteshaam balam bheemaabhirakshitam ||","spli":null,"splr":null,"en":"Yet insufficient seems this army of ours, though marshalled by Bhîshma, while that army of theirs seems sufficient, though marshalled by Bhîma;","en2":"\"This our army defended by Bhishma (is) impossible to be counted, but that army of theirs, defended by Bhima (is) easy to number.","en2r":null,"rv":null,"kid":null},{"v":11,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अयनेषु च सर्वेषु यथाभागमवस्थिताः ।\nभीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि ॥","iast":"ayaneṣu ca sarveṣu yathābhāgamavasthitāḥ |\nbhīṣmamevābhirakṣantu bhavantaḥ sarva eva hi ||","read":"ayaneshu cha sarveshu yathaabhaagamavasthitaah |\nbheeshmamevaabhirakshantu bhavantah sarva eva hi ||","spli":null,"splr":null,"en":"Therefore in the rank and file let all, standing firmly in their respective divisions, guard Bhîshma, even all ye generals.","en2":"\"(Now) do, being stationed in your proper places in the divisions of the army, support Bhishma alone.\"","en2r":null,"rv":null,"kid":null},{"v":12,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः ।\nसिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान् ॥","iast":"tasya saṃjanayanharṣaṃ kuruvṛddhaḥ pitāmahaḥ |\nsiṃhanādaṃ vinadyoccaiḥ śaṅkhaṃ dadhmau pratāpavān ||","read":"tasya samjanayanharsham kuruvriddhah pitaamahah |\nsimhanaadam vinadyochchaih shankham dadhmau prataapavaan ||","spli":null,"splr":null,"en":"To enhearten him, the Ancient of the Kurus, the Grandsire, the glorious, blew his conch, sounding on high a lion's roar.","en2":"That powerful, oldest of the Kurus, Bhishma the grandsire, in order to cheer Duryodhana, now sounded aloud a lion-roar and blew his conch.","en2r":null,"rv":null,"kid":null},{"v":13,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः ।\nसहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत् ॥","iast":"tataḥ śaṅkhāśca bheryaśca paṇavānakagomukhāḥ |\nsahasaivābhyahanyanta sa śabdastumulo’bhavat ||","read":"tatah shankhaashcha bheryashcha panavaanakagomukhaah |\nsahasaivaabhyahanyanta sa shabdastumulo'bhavat ||","spli":null,"splr":null,"en":"Then conches and kettledrums, tabors and drums and cowhorns, suddenly blared forth, and the sound was tumultuous.","en2":"Then following Bhishma, conches and kettle-drums, tabors, trumpets and cowhorns blared forth suddenly from the Kaurava side and the noise was tremendous.","en2r":null,"rv":null,"kid":null},{"v":14,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ ।\nमाधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः ॥","iast":"tataḥ śvetairhayairyukte mahati syandane sthitau |\nmādhavaḥ pāṇḍavaścaiva divyau śaṅkhau pradadhmatuḥ ||","read":"tatah shvetairhayairyukte mahati syandane sthitau |\nmaadhavah paandavashchaiva divyau shankhau pradadhmatuh ||","spli":null,"splr":null,"en":"Then, stationed in their great war-chariot, yoked to white horses, Mâdhava and the son of Pându blew their divine conches.","en2":"Then, also, Mâdhava and Pândava, stationed in their magnificent chariot yoked with white horses, blew their divine conches with a furious noise.","en2r":null,"rv":null,"kid":null},{"v":15,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः ।\nपौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः ॥","iast":"pāñcajanyaṃ hṛṣīkeśo devadattaṃ dhanaṃjayaḥ |\npauṇḍraṃ dadhmau mahāśaṅkhaṃ bhīmakarmā vṛkodaraḥ ||","read":"paanchajanyam hrisheekesho devadattam dhanamjayah |\npaundram dadhmau mahaashankham bheemakarmaa vrikodarah ||","spli":null,"splr":null,"en":"Pânchajanya by Hrishîkesha, and Devadatta by Dhananjaya. Vrikodara of terrible deeds blew his mighty conch, Paundra;","en2":"Hrishikesha blew the Pânchajanya, Dhananjaya, the Devadatta, and Vrikodara, the doer of terrific deeds, his large conch Paundra.","en2r":null,"rv":null,"kid":null},{"v":16,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः ।\nनकुलः सहदेवश्च सुघोषमणिपुष्पकौ ॥","iast":"anantavijayaṃ rājā kuntīputro yudhiṣṭhiraḥ |\nnakulaḥ sahadevaśca sughoṣamaṇipuṣpakau ||","read":"anantavijayam raajaa kunteeputro yudhishthirah |\nnakulah sahadevashcha sughoshamanipushpakau ||","spli":null,"splr":null,"en":"The King Yudhishthira, the son of Kuntî, blew Anantavijaya; Nakula and Sahadeva, Sughosha and Manipushpaka.","en2":"King Yudhishthira, son of Kunti, blew the conch named Anantavijaya, and Nakula and Sahadeva, their Sughosha and Manipushpaka.","en2r":null,"rv":null,"kid":null},{"v":17,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"काश्यश्च परमेष्वासः शिखण्डी च महारथः ।\nधृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः ॥","iast":"kāśyaśca parameṣvāsaḥ śikhaṇḍī ca mahārathaḥ |\ndhṛṣṭadyumno virāṭaśca sātyakiścāparājitaḥ ||","read":"kaashyashcha parameshvaasah shikhandee cha mahaarathah |\ndhrishtadyumno viraatashcha saatyakishchaaparaajitah ||","spli":null,"splr":null,"en":"And Kâshya, of the great bow and Shikhandî, the mighty car-warrior, Drishtadyumna and Virâta and Sâtyaki, the unconquered.","en2":"The expert bowman, king of Kâshi, and the great warrior Shikhandi, [paragraph continues] Dhrishtadyumna and Virâta and the unconquered Sâtyaki;","en2r":null,"rv":null,"kid":null},{"v":18,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते ।\nसौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक् ॥","iast":"drupado draupadeyāśca sarvaśaḥ pṛthivīpate |\nsaubhadraśca mahābāhuḥ śaṅkhāndadhmuḥ pṛthakpṛthak ||","read":"drupado draupadeyaashcha sarvashah prithiveepate |\nsaubhadrashcha mahaabaahuh shankhaandadhmuh prithakprithak ||","spli":null,"splr":null,"en":"Drupada and the Draupadeyas, O Lord of earth, and Saubhadra, the mighty-armed, on all sides their several conches blew.","en2":"O Lord of Earth! Drupada and the sons of Draupadi, and the mighty-armed son of Subhadrâ, all, also blew each his own conch.","en2r":null,"rv":null,"kid":null},{"v":19,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत् ।\nनभश्च पृथिवीं चैव तुमुलो व्यनुनादयन् ॥","iast":"sa ghoṣo dhārtarāṣṭrāṇāṃ hṛdayāni vyadārayat |\nnabhaśca pṛthivīṃ caiva tumulo vyanunādayan ||","read":"sa ghosho dhaartaraashtraanaam hridayaani vyadaarayat |\nnabhashcha prithiveem chaiva tumulo vyanunaadayan ||","spli":null,"splr":null,"en":"That tumultuous uproar rent the hearts of the sons of Dhritarâshtra, filling the earth and sky with sound.","en2":"And the terrific noise resounding throughout heaven and earth rent the hearts of Dhritarâshtra's party.","en2r":null,"rv":null,"kid":null},{"v":20,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः ।\nप्रवृत्ते शस्त्रसंपाते धनुरुद्यम्य पाण्डवः ॥","iast":"atha vyavasthitān dṛṣṭvā dhārtarāṣṭrānkapidhvajaḥ |\npravṛtte śastrasaṃpāte dhanurudyamya pāṇḍavaḥ ||","read":"atha vyavasthitaan drishtvaa dhaartaraashtraankapidhvajah |\npravritte shastrasampaate dhanurudyamya paandavah ||","spli":null,"splr":null,"en":"Then, beholding the sons of Dhritarâshtra standing arrayed, and flight of missiles about to begin, he whose crest is an ape, the son of Pându, took up his bow,","en2":"Then, O Lord of Earth, seeing Dhritarâshtra's party standing marshalled and the shooting about to begin, that Pândava whose ensign was the monkey, raising his bow, said the following words to Krishna:","en2r":null,"rv":null,"kid":null},{"v":21,"sp":"sanjaya","spm":"arjuna","spl":"अर्जुन उवाच","spp":"between the half-verses","sa":"हृषीकेशं तदा वाक्यमिदमाह महीपते ।\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत ॥","iast":"hṛṣīkeśaṃ tadā vākyamidamāha mahīpate |\nsenayorubhayormadhye rathaṃ sthāpaya me’cyuta ||","read":"hrisheekesham tadaa vaakyamidamaaha maheepate |\nsenayorubhayormadhye ratham sthaapaya me'chyuta ||","spli":"arjuna uvāca","splr":"arjuna uvaacha","en":"And spake this word to Hrishîkesha, O Lord of Earth: Arjuna said: In the midst, between the two armies, stay my chariot, O Achyuta,","en2":"Place my chariot, O Achyuta! between the two armies that I may see those who stand here prepared for war. On this eve of battle (let me know) with whom I have to fight.","en2r":"1.21-22","rv":null,"kid":null},{"v":22,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान् ।\nकैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे ॥","iast":"yāvadetānnirīkṣe’haṃ yoddhukāmānavasthitān |\nkairmayā saha yoddhavyamasminraṇasamudyame ||","read":"yaavadetaannireekshe'ham yoddhukaamaanavasthitaan |\nkairmayaa saha yoddhavyamasminranasamudyame ||","spli":null,"splr":null,"en":"That I may behold these standing, longing for battle, with whom I must strive in this outbreaking war,","en2":"Place my chariot, O Achyuta! between the two armies that I may see those who stand here prepared for war. On this eve of battle (let me know) with whom I have to fight.","en2r":"1.21-22","rv":null,"kid":null},{"v":23,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः ।\nधार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः ॥","iast":"yotsyamānānavekṣe’haṃ ya ete’tra samāgatāḥ |\ndhārtarāṣṭrasya durbuddheryuddhe priyacikīrṣavaḥ ||","read":"yotsyamaanaanavekshe'ham ya ete'tra samaagataah |\ndhaartaraashtrasya durbuddheryuddhe priyachikeershavah ||","spli":null,"splr":null,"en":"And gaze on those here gathered together ready to fight, desirous of pleasing in battle the evil-minded son of Dhritarâshtra.","en2":"For I desire to observe those who are assembled here for fight, wishing to please the evil-minded Duryodhana by taking his side on this battle-field.","en2r":null,"rv":null,"kid":null},{"v":24,"sp":"sanjaya","spm":null,"spl":"संजय उवाच","spp":"before","sa":"एवमुक्तो हृषीकेशो गुडाकेशेन भारत ।\nसेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम् ॥","iast":"evamukto hṛṣīkeśo guḍākeśena bhārata |\nsenayorubhayormadhye sthāpayitvā rathottamam ||","read":"evamukto hrisheekesho gudaakeshena bhaarata |\nsenayorubhayormadhye sthaapayitvaa rathottamam ||","spli":"saṃjaya uvāca","splr":"samjaya uvaacha","en":"Sanjaya said: Thus addressed by Gudâkesha, Hrishîkesha, O Bhârata, having stayed that best of chariots in the midst, between the two armies,","en2":"Commanded thus by Gudâkesha, Hrishikesha, O Bhârata, drove that grandest of chariots to a place between the two hosts, facing Bhishma, Drona and all the rulers of the earth, and then spoke thus, \"Behold, O Pârtha, all the Kurus gathered together!\"","en2r":"1.24-25","rv":null,"kid":null},{"v":25,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम् ।\nउवाच पार्थ पश्यैतान्समवेतान्कुरूनिति ॥","iast":"bhīṣmadroṇapramukhataḥ sarveṣāṃ ca mahīkṣitām |\nuvāca pārtha paśyaitānsamavetānkurūniti ||","read":"bheeshmadronapramukhatah sarveshaam cha maheekshitaam |\nuvaacha paartha pashyaitaansamavetaankurooniti ||","spli":null,"splr":null,"en":"Over against Bhîshma, Drona and all the rulers of the world, said: \"O Pârtha, behold these Kurus gathered together.\"","en2":"Commanded thus by Gudâkesha, Hrishikesha, O Bhârata, drove that grandest of chariots to a place between the two hosts, facing Bhishma, Drona and all the rulers of the earth, and then spoke thus, \"Behold, O Pârtha, all the Kurus gathered together!\"","en2r":"1.24-25","rv":null,"kid":null},{"v":26,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"तत्रापश्यत्स्थितान्पार्थः पितॄनथ पितामहान् ।\nआचार्यान्मातुलान्भ्रातॄन्पुत्रान्पौत्रान्सखींस्तथा ॥","iast":"tatrāpaśyatsthitānpārthaḥ pitṝnatha pitāmahān |\nācāryānmātulānbhrātṝnputrānpautrānsakhīṃstathā ||","read":"tatraapashyatsthitaanpaarthah pitreenatha pitaamahaan |\naachaaryaanmaatulaanbhraatreenputraanpautraansakheemstathaa ||","spli":null,"splr":null,"en":"Then saw Pârtha standing there, uncles and grandfathers, teachers, mother's brothers, cousins, sons and grandsons, comrades,","en2":"Then saw Pârtha stationed there in both the armies, grandfathers, fathers-in-law and uncles, brothers and cousins, his own and their sons and grandsons, and comrades, teachers, and other friends as well.","en2r":null,"rv":null,"kid":null},{"v":27,"sp":"sanjaya","spm":null,"spl":null,"spp":null,"sa":"श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि ।\nतान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान् ॥","iast":"śvaśurānsuhṛdaścaiva senayorubhayorapi |\ntānsamīkṣya sa kaunteyaḥ sarvānbandhūnavasthitān ||","read":"shvashuraansuhridashchaiva senayorubhayorapi |\ntaansameekshya sa kaunteyah sarvaanbandhoonavasthitaan ||","spli":null,"splr":null,"en":"Fathers-in-law and benefactors also in both armies; seeing all these kinsmen thus standing arrayed, Kaunteya,","en2":"Then he, the son of Kunti, seeing all those kinsmen stationed in their ranks, spoke thus sorrowfully, filled with deep compassion.","en2r":null,"rv":null,"kid":null},{"v":28,"sp":"sanjaya","spm":"arjuna","spl":"अर्जुन उवाच","spp":"between the half-verses","sa":"कृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत् ।\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् ॥","iast":"kṛpayā parayā’’viṣṭo viṣīdannidamabravīt |\ndṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam ||","read":"kripayaa parayaa''vishto visheedannidamabraveet |\ndrishtvemam svajanam krishna yuyutsum samupasthitam ||","spli":"arjuna uvāca","splr":"arjuna uvaacha","en":"Deeply moved to pity, thus uttered in sadness: Arjuna said: Seeing these my kinsmen, O Krishna, arrayed, eager to fight,","en2":null,"en2r":null,"rv":null,"kid":null},{"v":29,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"सीदन्ति मम गात्राणि मुखं च परिशुष्यति ।\nवेपथुश्च शरीरे मे रोमहर्षश्च जायते ॥","iast":"sīdanti mama gātrāṇi mukhaṃ ca pariśuṣyati |\nvepathuśca śarīre me romaharṣaśca jāyate ||","read":"seedanti mama gaatraani mukham cha parishushyati |\nvepathushcha shareere me romaharshashcha jaayate ||","spli":null,"splr":null,"en":"My limbs fail and my mouth is parched, my body quivers, and my hair stands on end,","en2":"Seeing, O Krishna, these my kinsmen gathered here, eager for fight, my limbs fail me, and my mouth is parched up. I shiver all over, and my hair stands on end. The bow Gândiva slips from my hand, and my skin burns.","en2r":null,"rv":null,"kid":null},{"v":30,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते ।\nन च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः ॥","iast":"gāṇḍīvaṃ sraṃsate hastāttvakcaiva paridahyate |\nna ca śaknomyavasthātuṃ bhramatīva ca me manaḥ ||","read":"gaandeevam sramsate hastaattvakchaiva paridahyate |\nna cha shaknomyavasthaatum bhramateeva cha me manah ||","spli":null,"splr":null,"en":"Gândîva slips from my hand, and my skin burns all over, I am not able to stand, my mind is whirling,","en2":"Neither, O Keshava, can I stand upright. My mind is in a whirl. And I see adverse omens.","en2r":null,"rv":null,"kid":null},{"v":31,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"निमित्तानि च पश्यामि विपरीतानि केशव ।\nन च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे ॥","iast":"nimittāni ca paśyāmi viparītāni keśava |\nna ca śreyo’nupaśyāmi hatvā svajanamāhave ||","read":"nimittaani cha pashyaami vipareetaani keshava |\nna cha shreyo'nupashyaami hatvaa svajanamaahave ||","spli":null,"splr":null,"en":"And I see adverse omens, O Keshava. Nor do I foresee any advantage from slaying kinsmen in battle.","en2":"Neither, O Krishna, do I see any good in killing these my own people in battle. I desire neither victory nor empire, nor yet pleasure.","en2r":null,"rv":null,"kid":null},{"v":32,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च ।\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा ॥","iast":"na kāṅkṣe vijayaṃ kṛṣṇa na ca rājyaṃ sukhāni ca |\nkiṃ no rājyena govinda kiṃ bhogairjīvitena vā ||","read":"na kaankshe vijayam krishna na cha raajyam sukhaani cha |\nkim no raajyena govinda kim bhogairjeevitena vaa ||","spli":null,"splr":null,"en":"For I desire not victory, O Krishna, nor kingdom, nor pleasures; what is kingdom to us, O Govinda, what enjoyment or even life?","en2":"Of what avail is dominion to us, of what avail are pleasures and even life, if these, O Govinda! for whose sake it is desired that empire, enjoyment and pleasure should be ours, themselves stand here in battle, having renounced life and wealth—Teachers, uncles, sons and also grandfathers, maternal uncles, fathers-in-law, grandsons, brothers-in-law, besides other kinsmen.","en2r":"1.32-34","rv":null,"kid":null},{"v":33,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च ।\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च ॥","iast":"yeṣāmarthe kāṅkṣitaṃ no rājyaṃ bhogāḥ sukhāni ca |\nta ime’vasthitā yuddhe prāṇāṃstyaktvā dhanāni ca ||","read":"yeshaamarthe kaankshitam no raajyam bhogaah sukhaani cha |\nta ime'vasthitaa yuddhe praanaamstyaktvaa dhanaani cha ||","spli":null,"splr":null,"en":"Those for whose sake we desire kingdom, enjoyments and pleasures, they stand here in battle, abandoning life and riches—","en2":"Of what avail is dominion to us, of what avail are pleasures and even life, if these, O Govinda! for whose sake it is desired that empire, enjoyment and pleasure should be ours, themselves stand here in battle, having renounced life and wealth—Teachers, uncles, sons and also grandfathers, maternal uncles, fathers-in-law, grandsons, brothers-in-law, besides other kinsmen.","en2r":"1.32-34","rv":null,"kid":null},{"v":34,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"आचार्याः पितरः पुत्रास्तथैव च पितामहाः ।\nमातुलाः श्वशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा ॥","iast":"ācāryāḥ pitaraḥ putrāstathaiva ca pitāmahāḥ |\nmātulāḥ śvaśurāḥ pautrāḥ śyālāḥ sambandhinastathā ||","read":"aachaaryaah pitarah putraastathaiva cha pitaamahaah |\nmaatulaah shvashuraah pautraah shyaalaah sambandhinastathaa ||","spli":null,"splr":null,"en":"Teachers, fathers, sons, as well as grandfathers, mother's brothers, fathers-in-law, grandsons, brothers-in-law, and other relatives.","en2":"Of what avail is dominion to us, of what avail are pleasures and even life, if these, O Govinda! for whose sake it is desired that empire, enjoyment and pleasure should be ours, themselves stand here in battle, having renounced life and wealth—Teachers, uncles, sons and also grandfathers, maternal uncles, fathers-in-law, grandsons, brothers-in-law, besides other kinsmen.","en2r":"1.32-34","rv":null,"kid":null},{"v":35,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन ।\nअपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते ॥","iast":"etānna hantumicchāmi ghnato’pi madhusūdana |\napi trailokyarājyasya hetoḥ kiṃ nu mahīkṛte ||","read":"etaanna hantumichchhaami ghnato'pi madhusoodana |\napi trailokyaraajyasya hetoh kim nu maheekrite ||","spli":null,"splr":null,"en":"These I do not wish to kill, though myself slain, O Madhusûdana, even for the sake of the kingship of the three worlds; how then for earth?","en2":"Even though these were to kill me, O slayer of Madhu, I could not wish to kill them, not even for the sake of dominion over the three worlds, how much less for the sake of the earth!","en2r":null,"rv":null,"kid":null},{"v":36,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन ।\nपापमेवाश्रयेदस्मान्हत्वैतानाततायिनः ॥","iast":"nihatya dhārtarāṣṭrānnaḥ kā prītiḥ syājjanārdana |\npāpamevāśrayedasmānhatvaitānātatāyinaḥ ||","read":"nihatya dhaartaraashtraannah kaa preetih syaajjanaardana |\npaapamevaashrayedasmaanhatvaitaanaatataayinah ||","spli":null,"splr":null,"en":"Slaying these sons of Dhritarâshtra, what pleasure can be ours, O Janârdana? Killing these desperadoes, sin will but take hold of us.","en2":"What pleasure indeed could be ours, O Jnanârdana, from killing these sons of Dhritarâshtra? Sin only could take hold of us by the slaying of these felons.","en2r":null,"rv":null,"kid":null},{"v":37,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान् ।\nस्वजनं हि कथं हत्वा सुखिनः स्याम माधव ॥","iast":"tasmānnārhā vayaṃ hantuṃ dhārtarāṣṭrānsvabāndhavān |\nsvajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava ||","read":"tasmaannaarhaa vayam hantum dhaartaraashtraansvabaandhavaan |\nsvajanam hi katham hatvaa sukhinah syaama maadhava ||","spli":null,"splr":null,"en":"Therefore we should not kill the sons of Dhritarâshtra, our relatives; for how, killing our kinsmen, may we be happy, O Mâdhava?","en2":"Therefore ought we not to kill our kindred, the sons of Dhritarâshtra. For how could we, O Mâdhava, gain happiness by the slaying of our own kinsmen?","en2r":null,"rv":null,"kid":null},{"v":38,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"यद्यप्येते न पश्यन्ति लोभोपहतचेतसः ।\nकुलक्षयकृतं दोषं मित्रद्रोहे च पातकम् ॥","iast":"yadyapyete na paśyanti lobhopahatacetasaḥ |\nkulakṣayakṛtaṃ doṣaṃ mitradrohe ca pātakam ||","read":"yadyapyete na pashyanti lobhopahatachetasah |\nkulakshayakritam dosham mitradrohe cha paatakam ||","spli":null,"splr":null,"en":"Although these, with intelligence overpowered by greed, see no guilt in the destruction of a family, no crime in hostility to friends,","en2":"Though these, with understanding overpowered by greed, see no evil due to decay of families, and no sin in hostility to friends, why should we, O Janârdana, who see clearly the evil due to the decay of families, not turn away from this sin?","en2r":"1.38-39","rv":null,"kid":null},{"v":39,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम् ।\nकुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन ॥","iast":"kathaṃ na jñeyamasmābhiḥ pāpādasmānnivartitum |\nkulakṣayakṛtaṃ doṣaṃ prapaśyadbhirjanārdana ||","read":"katham na jneyamasmaabhih paapaadasmaannivartitum |\nkulakshayakritam dosham prapashyadbhirjanaardana ||","spli":null,"splr":null,"en":"Why should not we learn to turn away from such a sin, O Janârdana, who see the evils in the destruction of a family?","en2":"Though these, with understanding overpowered by greed, see no evil due to decay of families, and no sin in hostility to friends, why should we, O Janârdana, who see clearly the evil due to the decay of families, not turn away from this sin?","en2r":"1.38-39","rv":null,"kid":null},{"v":40,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः ।\nधर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत ॥","iast":"kulakṣaye praṇaśyanti kuladharmāḥ sanātanāḥ |\ndharme naṣṭe kulaṃ kṛtsnamadharmo’bhibhavatyuta ||","read":"kulakshaye pranashyanti kuladharmaah sanaatanaah |\ndharme nashte kulam kritsnamadharmo'bhibhavatyuta ||","spli":null,"splr":null,"en":"In the destruction of a family the immemorial family traditions perish; in the perishing of tradition, lawlessness overcomes the whole family;","en2":"On the decay of a family the immemorial religious rites of that family die out. On the destruction of spirituality, impiety further overwhelms the whole of the family.","en2r":null,"rv":null,"kid":null},{"v":41,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः ।\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः ॥","iast":"adharmābhibhavātkṛṣṇa praduṣyanti kulastriyaḥ |\nstrīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṅkaraḥ ||","read":"adharmaabhibhavaatkrishna pradushyanti kulastriyah |\nstreeshu dushtaasu vaarshneya jaayate varnasankarah ||","spli":null,"splr":null,"en":"Owing to predominance of lawlessness, O Krishna, the women of the family become corrupt; women corrupted, O Vârshneya, there ariseth caste confusion;","en2":"On the prevalence of impiety, O Krishna, the women of the family become corrupt; and women being corrupted, there arises, O Vârshneya, intermingling of castes.","en2r":null,"rv":null,"kid":null},{"v":42,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"सङ्करो नरकायैव कुलघ्नानां कुलस्य च ।\nपतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः ॥","iast":"saṅkaro narakāyaiva kulaghnānāṃ kulasya ca |\npatanti pitaro hyeṣāṃ luptapiṇḍodakakriyāḥ ||","read":"sankaro narakaayaiva kulaghnaanaam kulasya cha |\npatanti pitaro hyeshaam luptapindodakakriyaah ||","spli":null,"splr":null,"en":"This confusion draggeth to hell the slayers of the family, and the family; for their ancestors fall, deprived of rice-balls and libations.","en2":"Admixture of castes, indeed, is for the hell of the family and the destroyers of the family; their ancestors fall, deprived of the offerings of rice-ball and water.","en2r":null,"rv":null,"kid":null},{"v":43,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः ।\nउत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः ॥","iast":"doṣairetaiḥ kulaghnānāṃ varṇasaṅkarakārakaiḥ |\nutsādyante jātidharmāḥ kuladharmāśca śāśvatāḥ ||","read":"doshairetaih kulaghnaanaam varnasankarakaarakaih |\nutsaadyante jaatidharmaah kuladharmaashcha shaashvataah ||","spli":null,"splr":null,"en":"By these caste-confusing misdeeds of the slayers of the family, the everlasting caste customs and family customs are abolished.","en2":"By these misdeeds of the destroyers of the family, bringing about confusion of castes, are the immemorial religious rites of the caste and the family destroyed.","en2r":null,"rv":null,"kid":null},{"v":44,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन ।\nनरकेऽनियतं वासो भवतीत्यनुशुश्रुम ॥","iast":"utsannakuladharmāṇāṃ manuṣyāṇāṃ janārdana |\nnarake’niyataṃ vāso bhavatītyanuśuśruma ||","read":"utsannakuladharmaanaam manushyaanaam janaardana |\nnarake'niyatam vaaso bhavateetyanushushruma ||","spli":null,"splr":null,"en":"The abode of the men whose family customs are extinguished, O Janârdana, is everlastingly in hell. Thus have we heard.","en2":"We have heard, O Janârdana, that inevitable is the dwelling in hell of those men in whose families religious practices have been destroyed.","en2r":null,"rv":null,"kid":null},{"v":45,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"अहो बत महत्पापं कर्तुं व्यवसिता वयम् ।\nयद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः ॥","iast":"aho bata mahatpāpaṃ kartuṃ vyavasitā vayam |\nyadrājyasukhalobhena hantuṃ svajanamudyatāḥ ||","read":"aho bata mahatpaapam kartum vyavasitaa vayam |\nyadraajyasukhalobhena hantum svajanamudyataah ||","spli":null,"splr":null,"en":"Alas! in committing a great sin are we engaged, we who are endeavouring to kill our kindred from greed of the pleasures of kingship.","en2":"Alas, we are involved in a great sin, in that we are prepared to slay our kinsmen, from greed of the pleasures of a kingdom!","en2r":null,"rv":null,"kid":null},{"v":46,"sp":"arjuna","spm":null,"spl":null,"spp":null,"sa":"यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः ।\nधार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत् ॥","iast":"yadi māmapratīkāramaśastraṃ śastrapāṇayaḥ |\ndhārtarāṣṭrā raṇe hanyustanme kṣemataraṃ bhavet ||","read":"yadi maamaprateekaaramashastram shastrapaanayah |\ndhaartaraashtraa rane hanyustanme kshemataram bhavet ||","spli":null,"splr":null,"en":"If the sons of Dhritarâshtra, weapon in hand, should slay me, unresisting, unarmed, in the battle, that would for me be the better.","en2":"Verily, if the sons of Dhritarâshtra, weapons in hand, were to slay me, unresisting and unarmed, in the battle, that would be better for me.","en2r":null,"rv":null,"kid":null},{"v":47,"sp":"sanjaya","spm":null,"spl":"सञ्जय उवाच","spp":"before","sa":"एवमुक्त्वाऽर्जुनः संख्ये रथोपस्थ उपाविशत् ।\nविसृज्य सशरं चापं शोकसंविग्नमानसः ॥","iast":"evamuktvā’rjunaḥ saṃkhye rathopastha upāviśat |\nvisṛjya saśaraṃ cāpaṃ śokasaṃvignamānasaḥ ||","read":"evamuktvaa'rjunah samkhye rathopastha upaavishat |\nvisrijya sasharam chaapam shokasamvignamaanasah ||","spli":"sañjaya uvāca","splr":"sanjaya uvaacha","en":"Sanjaya said: Having thus spoken on the battle-field, Arjuna sank down on the seat of the chariot, casting away his bow and arrow, his mind overborne by grief.","en2":"Speaking thus in the midst of the battle-field, Arjuna casting away his bow and arrows, sank down on the seat of his chariot, with his mind distressed with sorrow.","en2r":null,"rv":null,"kid":null}];
